import os
import sys

def rainbow_table_attack(trove, hash):
    for word, hashed_word in trove.items():
        if hashed_word == hash:
            return word
    return None

def main():
    if len(sys.argv)!= 3:
        print("Usage: python rainbow_table_attack.py <trove> <hash>")
        sys.exit(1)

    trove = {}
    with open(sys.argv[1], 'r') as f:
        for line in f:
            word, hashed_word = line.strip().split(':')
            trove[word] = hashed_word

    hash = sys.argv[2]
    result = rainbow_table_attack(trove, hash)

    if result:
        print("Password: %s" % result)
    else:
        print("Password not found in the trove")

if __name__ == "__main__":
    main()

