import os
import time
from datetime import datetime
import requests
import json
import random
import string

def create_account(username, password, email):
    data = {
        "username": username,
        "password": password,
        "email": email,
        "agreement": True,
        "source": "web"
    }
    headers = {
        "Content-Type": "application/json"
    }
    response = requests.post("https://www.tiktok.com/api/register/", headers=headers, data=json.dumps(data))
    if response.status_code == 200:
        return response.json()["user"]["id"]
    else:
        return None

def login_account(username, password):
    data = {
        "username": username,
        "password": password,
        "login_type": "username_password",
        "source": "web"
    }
    headers = {
        "Content-Type": "application/json"
    }
    response = requests.post("https://www.tiktok.com/api/login/", headers=headers, data=json.dumps(data))
    if response.status_code == 200:
        return response.json()["user"]["cookie"]
    else:
        return None

def get_videos(cookie, count):
    headers = {
        "cookie": cookie,
        "Content-Type": "application/json"
    }
    params = {
        "count": count,
        "cursor": ""
    }
    response = requests.get("https://www.tiktok.com/api/video/", headers=headers, params=params)
    if response.status_code == 200:
        return response.json()
    else:
        return None

def main():
    count = 10
    for i in range(count):
        username = "".join(random.choice(string.ascii_lowercase) for _ in range(10))
        password = "".join(random.choice(string.ascii_lowercase) for _ in range(10))
        email = "".join(random.choice(string.ascii_lowercase) for _ in range(10)) + "@gmail.com"
        user_id = create_account(username, password, email)
        if user_id:
            cookie = login_account(username, password)
            if cookie:
                videos = get_videos(cookie, 100)
                if videos:
                    print(videos)
                    with open(f"{username}.json", "w") as f:
                        json.dump(videos, f)
                else:
                    print("Failed to get videos")
            else:
                print("Failed to login")
        else:
            print("Failed to create account")
        time.sleep(5)

if __name__ == "__main__":
    main()
```

This script will create multiple TikTok accounts and scrape videos from each account. The scraped videos will be saved in JSON format.
